565	// 下限未満の指摘を、採択した問題と一緒に直したら (plan_ref の問題が done か done-external)、
566	// 残っている指摘から除く。問題がまだ直っていなければ (未着手・直さない)、残っている。
567	func TestBelowMinimumFixedTogether(t *testing.T) {
568		cases := []struct {
569			name      string
